DO $$ DECLARE t text; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' AND tablename IN ('users','sessions','registrations','email_outbox','audit_log','api_rate_limits','schema_migrations') LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN EXECUTE format('REVOKE ALL ON public.%I FROM anon',t); END IF; IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN EXECUTE format('REVOKE ALL ON public.%I FROM authenticated',t); END IF; END LOOP; IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON SEQUENCE public.reg_seq FROM anon; END IF; IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON SEQUENCE public.reg_seq FROM authenticated; END IF; END $$;
CREATE OR REPLACE FUNCTION public.prevent_hypehouse_audit_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'audit_log is append-only'; END; $$;
REVOKE ALL ON FUNCTION public.prevent_hypehouse_audit_mutation() FROM PUBLIC;
DROP TRIGGER IF EXISTS hypehouse_audit_append_only_rows ON public.audit_log;
CREATE TRIGGER hypehouse_audit_append_only_rows BEFORE UPDATE OR DELETE ON public.audit_log FOR EACH ROW EXECUTE FUNCTION public.prevent_hypehouse_audit_mutation();
DROP TRIGGER IF EXISTS hypehouse_audit_append_only_truncate ON public.audit_log;
CREATE TRIGGER hypehouse_audit_append_only_truncate BEFORE TRUNCATE ON public.audit_log FOR EACH STATEMENT EXECUTE FUNCTION public.prevent_hypehouse_audit_mutation();
